#[derive(Deserialize)]
#[serde(tag = "type")]                 // the discriminator is the router
enum Wire {
    Csv { raw: String }, Xml { document: String },
    #[serde(other)] Unknown,           // forward-compatible, explicit catch-all
}
fn normalize(raw: &str) -> Result<Canonical, NormalizeError> {
    match serde_json::from_str::<Wire>(raw)? {      // serde dispatches on the tag
        Wire::Csv { raw } => Canonical::from_csv(&raw),
        Wire::Xml { document } => Canonical::from_xml(&document),
        Wire::Unknown => Err(NormalizeError::UnsupportedFormat),
    }
}
